.fade-in {
  animation: fadeIn 600ms cubic-bezier(.22,.61,.36,1) both;
}
@keyframes fadeIn {
  from { opacity: 0; }
  to   { opacity: 1; }
}

.slide-up {
  animation: slideUp 700ms cubic-bezier(.16,1,.3,1) both;
}
@keyframes slideUp {
  from { opacity: 0; transform: translateY(32px); }
  to   { opacity: 1; transform: none; }
}

.scale-in {
  animation: scaleIn 500ms cubic-bezier(.34,1.56,.64,1) both;
}
@keyframes scaleIn {
  from { opacity: 0; transform: scale(0.6); }
  to   { opacity: 1; transform: scale(1); }
}

.blur-in {
  animation: blurIn 900ms cubic-bezier(.22,.61,.36,1) both;
}
@keyframes blurIn {
  from { opacity: 0; filter: blur(14px); transform: scale(1.06); }
  to   { opacity: 1; filter: blur(0);  transform: scale(1); }
}

.flip-in {
  backface-visibility: hidden;
  animation: flipIn 800ms cubic-bezier(.16,1,.3,1) both;
}
@keyframes flipIn {
  from { opacity: 0; transform: perspective(800px) rotateX(90deg); }
  to   { opacity: 1; transform: perspective(800px) rotateX(0); }
}

.item {
  animation: rise 550ms cubic-bezier(.16,1,.3,1) both;
  animation-delay: calc(var(--i) * 90ms);
}
@keyframes rise {
  from { opacity: 0; transform: translateY(24px); }
}
/* <li style="--i:0">, <li style="--i:1"> ... */

.reveal {
  animation: reveal 1000ms cubic-bezier(.65,0,.35,1) both;
}
@keyframes reveal {
  from { clip-path: inset(0 100% 0 0); }
  to   { clip-path: inset(0); }
}

.pulse {
  animation: pulse 1400ms ease-out infinite;
}
@keyframes pulse {
  0%   { transform: scale(1); box-shadow: 0 0 0 0 rgba(232,184,186,.55); }
  50%  { transform: scale(1.08); }
  100% { transform: scale(1); box-shadow: 0 0 0 22px rgba(232,184,186,0); }
