.shake {
  animation: shake 480ms ease-in-out;
}
@keyframes shake {
  20% { transform: translateX(-10px); }
  40% { transform: translateX(10px); }
  60% { transform: translateX(-6.0px); }
  80% { transform: translateX(6.0px); }
}

.bounce {
  transform-origin: 50% 100%;
  animation: bounce 900ms infinite;
}
@keyframes bounce {
  0%, 90%, 100% { transform: translateY(0) scale(1.15, 0.85);
                  animation-timing-function: cubic-bezier(.33,1,.68,1); }
  45% { transform: translateY(-70px);
        animation-timing-function: cubic-bezier(.32,0,.67,0); }
