@keyframes swing {
  17% { transform: rotate(15deg); }
  33% { transform: rotate(-12.0deg); }
  50% { transform: rotate(8.3deg); }
  67% { transform: rotate(-4.5deg); }
  83% { transform: rotate(1.8deg); }
