let x = 0, v = 0, target = 300;
const k = 180, c = 12, m = 1;
function step() {
  const dt = 1 / 60;
  const F = -k * (x - target) - c * v;
  v += (F / m) * dt;
  x += v * dt;
  el.style.transform = `translateX(${x}px)`;
  if (Math.abs(v) > 0.1 || Math.abs(x - target) > 0.1)
    requestAnimationFrame(step);
}
requestAnimationFrame(step);

