function render(progress) {            // 0 → 1
  const ps = Math.max(1, Math.round(36 + (1 - 36) * progress));
  const w = Math.ceil(W / ps), h = Math.ceil(H / ps);
  small.width = w; small.height = h;
  small.getContext('2d').drawImage(img, 0, 0, w, h);
  ctx.imageSmoothingEnabled = false;      // 모자이크 유지
  ctx.drawImage(small, 0, 0, w, h, 0, 0, w * ps, h * ps);
  drawNoise((1 - progress) * 0.6, ps); // 남은 만큼 노이즈
}
