let hx = 0, hy = 0; const pts = [];
function frame() {
  hx += (mouse.x - hx) * 0.3;       // lerp로 부드럽게 추적
  hy += (mouse.y - hy) * 0.3;
  pts.unshift([hx, hy]); pts.length = Math.min(pts.length, 28);
  ctx.clearRect(0, 0, W, H);
  ctx.shadowBlur = 16; ctx.shadowColor = 'rgba(232,184,186,.8)';
  for (let i = 1; i < pts.length; i++) {
    const k = 1 - i / pts.length;           // 뒤로 갈수록 가늘고 흐리게
    ctx.lineWidth = 12 * k;
    ctx.strokeStyle = `rgba(246,218,215,${k})`;
    ctx.beginPath(); ctx.moveTo(...pts[i-1]); ctx.lineTo(...pts[i]); ctx.stroke();
  }
  requestAnimationFrame(frame);
}

dots.forEach(d => {
  let fx = -(d.x - d.homeX) * 120, fy = -(d.y - d.homeY) * 120; // 복원력
  const dx = d.x - mouse.x, dy = d.y - mouse.y;
  const dist = Math.hypot(dx, dy) || 1;
  if (dist < 100) {                              // 반발력
    const k = (1 - dist / 100) * 12 * 400;
    fx += dx / dist * k; fy += dy / dist * k;
  }
  d.vx = (d.vx + fx * dt) * .88;                   // 감쇠
  d.vy = (d.vy + fy * dt) * .88;
  d.x += d.vx * dt; d.y += d.vy * dt;
});

const flakes = Array.from({ length: 140 }, () => ({
  x: Math.random() * W, y: Math.random() * H,
  r: (.4 + Math.random() * .6) * 3, phase: Math.random() * 6.28 }));
function frame(t, dt) {
  ctx.clearRect(0, 0, W, H);
  for (const f of flakes) {
    f.y += (20 + f.r * 14) * 1 * dt;             // 큰 눈일수록 빠르게
    f.x += (Math.sin(t * 1.2 + f.phase) * 12 + 0.3 * 30) * dt;
    if (f.y > H) { f.y = -5; f.x = Math.random() * W; } // 재사용
    ctx.globalAlpha = .35 + f.r / 3 * .6;
    ctx.beginPath(); ctx.arc(f.x, f.y, f.r, 0, Math.PI * 2); ctx.fill();
  }
}

const cols = Math.ceil(W / 18), rows = Math.ceil(H / 18);
const glow = new Float32Array(cols * rows);
function frame(dt) {
  if (Math.random() < 16 * dt)              // 초당 16개 점등
    glow[Math.floor(Math.random() * glow.length)] = 1;
  ctx.clearRect(0, 0, W, H);
  glow.forEach((g, i) => {
    glow[i] = Math.max(0, g - dt * 1000 / 1200);  // 서서히 소등
    ctx.fillStyle = `rgba(220,170,172,${.05 + glow[i] * .75})`;
    ctx.fillRect(i % cols * 18 + 1, (i / cols | 0) * 18 + 1, 16, 16);
  });
}

