function moveTo(btn) {
  const from = { left: pill.offsetLeft, width: pill.offsetWidth };
  const to   = { left: btn.offsetLeft,  width: btn.offsetWidth };
  const L = Math.min(from.left, to.left);
  const R = Math.max(from.left + from.width, to.left + to.width);
  const midW = /* 평균 너비 + (전체 범위 - 평균) × 0.6 */;
  pill.animate([
    { left: from.left + 'px', width: from.width + 'px' },
    { left: midLeft + 'px',   width: midW + 'px', offset: .5 },
    { left: to.left + 'px',   width: to.width + 'px' }
  ], { duration: 460, easing: 'cubic-bezier(.16,1,.3,1)', fill: 'forwards' });
}

function flip(items, mutate) {
  const first = new Map(items.map(el => [el, el.getBoundingClientRect()])); // F
  mutate();                                                // DOM 순서 변경
  items.forEach((el, i) => {
    const a = first.get(el), b = el.getBoundingClientRect(); // L
    const dx = a.left - b.left, dy = a.top - b.top;
    if (!dx && !dy) return;
    el.animate([{ transform: `translate(${dx}px,${dy}px)` },  // I
                { transform: 'none' }],                        // P
      { duration: 550, easing: 'cubic-bezier(.16,1,.3,1)', delay: i * 25 });
  });
}

