function scramble(el, text, chars) {
  let frame = 0;
  const tick = () => {
    let out = '', done = true;
    [...text].forEach((ch, i) => {
      if (frame >= i * 2 + 12) out += ch;          // 확정
      else { done = false; out += chars[Math.random() * chars.length | 0]; }
    });
    el.textContent = out;
    frame++;
    if (!done) setTimeout(tick, 40);
  };
  tick();
}

