letters.forEach((span, i) => {
  const off = {
    transform: `translate(${(Math.random() - .5) * 40}px, -40px)
                rotate(${(Math.random() - .5) * 50}deg) scale(1.3)`,
    filter: 'blur(14px)', opacity: 0 };
  const on = { transform: 'none', filter: 'blur(0)', opacity: 1 };
  span.animate([on, { ...off, offset: .4 }, { ...off, offset: .6 }, on],
    { duration: 2800, delay: i * 60, easing: 'ease-in-out' });
