/* JS: --hx = 50 + x*50 %, --angle = 115 + x*40 deg, --ry = x*12deg */

// 1) 2D 파동 방정식 (격자 176×N, 매 프레임 2회)
for (each cell k) next[k] = ((h[k-1] + h[k+1] + h[k-W] + h[k+W]) * 0.5 - prev[k]) * 0.985;
// 커서/손가락: 지나간 칸을 살짝 꺼뜨림, 클릭: 크게 꺼뜨림(물방울)

// 2) WebGL 셰이더: 높이맵 텍스처로 굴절 + 빛 그물
vec2 g   = vec2(hR - hL, hD - hU);           // 수면 기울기
float lap = hL + hR + hU + hD - 4.0 * h;     // 오목 = 빛이 모임
vec2 floorUV = uv + g * 0.12 * 1;    // 바닥 굴절
float web = exp(-abs(sin(q.x) + sin(q.y)) * 5.0); // q = 서로 비튼 좌표
col = floorTiles(floorUV) + tint * (web * 1 + max(-lap * 55.0, 0.0));

// 베를레 천 (26×22 점)
for (const pt of points) if (!pt.pinned) {
  const v = { x: (pt.x - pt.ox) * .985, y: (pt.y - pt.oy) * .985, z: (pt.z - pt.oz) * .97 };
  pt.ox = pt.x; pt.oy = pt.y; pt.oz = pt.z;
  const f = wind(pt, t) * 1 + gust * 1 + push(pt, pointer); // 앞쪽(z)으로 미는 힘
  pt.x += v.x + f.x*dt*dt;  pt.y += v.y + 520*dt*dt;  pt.z += v.z + f.z*dt*dt;
}
for (let i = 0; i < 4; i++)               // 거리 제약 반복
  for (const [a, b, L] of links) keepDistance(a, b, L);
// 윗줄은 커튼봉에 고정, 천 폭을 봉 간격보다 15% 넓게 → 주름
// 그리기: 칸마다 법선으로 밝기 → 오프스크린에 불투명하게 → 전체를 alpha 0.6로 한 번에 합성

// 육각 격자 가시 자리, 자기장 = 자석 거리의 가우시안
const S = magnet.strength * 1 + pulse;           // 클릭 시 pulse = 1 → 감소
for (const s of spikes) {
  const f = S * Math.exp(-dist2(s, magnet) / 0.2);
  const target = Math.max(0, (f - 0.2) / (1 - 0.2)) * Hmax; // 임계값 넘은 만큼만
  s.v += (target - s.h) * 180 * dt;  s.v *= Math.exp(-9 * dt);  s.h += s.v * dt; // 스프링
}
