  background-size: 250% 100%;
  -webkit-background-clip: text; background-clip: text; color: transparent;
  animation: shine 2400ms ease-in-out infinite;
}
@keyframes shine { from { background-position: 120% 0; } to { background-position: -20% 0; } }

.grad {
  background: linear-gradient(90deg, ...colors, firstColor);
  background-size: 200% 100%;
  -webkit-background-clip: text; background-clip: text; color: transparent;
  animation: flow 4000ms linear infinite;
}
@keyframes flow { to { background-position: 200% 0; } }

.glitch { position: relative; }
.glitch::before, .glitch::after {
  content: attr(data-text); position: absolute; inset: 0; mix-blend-mode: screen;
}
.glitch::before { color: #ff3b5c; }  .glitch::after { color: #3bf2ff; }
/* JS: 70ms마다 각 겹에 무작위 clip-path: inset(a% 0 b% 0)
