async function flipTo(cell, target) {
  while (cell.char !== target) {
    cell.char = nextChar(cell.char);           // 문자표 순서대로 한 칸씩
    cell.animate([{ transform: 'rotateX(0)' },
                  { transform: 'rotateX(-90deg)', offset: .5 },
                  { transform: 'rotateX(0)' }], { duration: 77 });
    await sleep(27.5); cell.textContent = cell.char; await sleep(27.5);
  }
}
// 칸마다 30ms씩 늦게 시작, 문구 사이 1600ms 대기

chars.forEach((ch, i) => {
  ch.style.transform = `translate(-50%,-50%) rotate(${i * 360 / chars.length}deg) translateY(-78px)`;
});
const spin = ring.animate([{ transform: 'rotate(0)' }, { transform: 'rotate(360deg)' }],
  { duration: 14000, iterations: Infinity });
badge.onpointerenter = () => spin.updatePlaybackRate(4);
badge.onpointerleave = () => spin.updatePlaybackRate(1);

words.forEach((w, j) => w.style.filter = j === i ? 'blur(0)' : 'blur(5px)');
frame.style.left   = word.offsetLeft + 'px';   // 네 모서리 괄호 프레임
frame.style.top    = word.offsetTop + 'px';
frame.style.width  = word.offsetWidth + 'px';
frame.style.height = word.offsetHeight + 'px';
