.caption span {
  display: inline-block;
  color: #fff;
}
.caption span.on {
  animation: hi 400ms cubic-bezier(.22,.61,.36,1) both;
}
@keyframes hi {
  0%   { color: #fff; transform: scale(1); }
  30%  { color: #ffe14d; transform: scale(1.14); }
  100% { color: #ffe14d; transform: scale(1); }
}

.typing span {
  opacity: 0;
  animation: type 2200ms steps(1, end) both;
}
/* 글자마다 animation-delay를 i × 2200/글자수 로 늘려 주세요 */
@keyframes type {
  to { opacity: 1; }
}

.pop-word {
  display: inline-block;
  animation: pop 420ms cubic-bezier(.34,1.56,.64,1) both;
}
@keyframes pop {
  0%   { transform: scale(.3); opacity: 0; }
  60%  { transform: scale(1.18); opacity: 1; }
  100% { transform: scale(1); opacity: 1; }
}

.slam {
  animation: slam 520ms cubic-bezier(.16,1,.3,1) both;
}
@keyframes slam {
  0%   { transform: scale(2.4); opacity: 0; }
  70%  { transform: scale(.96); opacity: 1; }
  100% { transform: scale(1);   opacity: 1; }
}

.box-caption {
  background: #000;
  transform-origin: left;
  animation: boxIn 700ms cubic-bezier(.16,1,.3,1) both;
}
@keyframes boxIn {
  from { transform: scaleX(0); }
  to   { transform: scaleX(1); }
}

.outline {
  -webkit-text-stroke: 3px #000;
  paint-order: stroke fill;
  animation: hue 900ms cubic-bezier(.65,0,.35,1) infinite alternate;
}
@keyframes hue {
  from { color: #fff; }
  to   { color: #ff3b5c; }
}

.line {
  clip-path: inset(0 0 100% 0);
  animation: reveal 650ms cubic-bezier(.16,1,.3,1) both;
}
@keyframes reveal {
  to { clip-path: inset(0 0 0 0); }
}

.char {
  display: inline-block;
  animation: charPop 500ms cubic-bezier(.34,1.56,.64,1) both;
}
/* 글자마다 animation-delay를 i × 간격으로 */
@keyframes charPop {
  from { transform: translateY(-40px); opacity: 0; }
  to   { transform: translateY(0);     opacity: 1; }
}

.bubble {
  transform-origin: 30% 100%;
  animation: bubble 480ms cubic-bezier(.34,1.56,.64,1) both;
}
@keyframes bubble {
  from { transform: scale(.4); opacity: 0; }
  to   { transform: scale(1);  opacity: 1; }
}

.cap-a {
  animation: out 560ms cubic-bezier(.22,.61,.36,1) both;
}
.cap-b {
  animation: in 560ms cubic-bezier(.22,.61,.36,1) both;
}
@keyframes out { to { opacity: 0; transform: translateY(-10px); } }
@keyframes in  { from { opacity: 0; transform: translateY(10px); } }

.ticker-text {
  white-space: nowrap;
  animation: scroll 6000ms linear infinite;
}
@keyframes scroll {
  from { transform: translateX(100%); }
  to   { transform: translateX(-100%); }
}

.lower-third .bar {
  transform-origin: left;
  animation: wipe 640ms cubic-bezier(.16,1,.3,1) both;
}
.lower-third .text {
  animation: slideIn 640ms cubic-bezier(.16,1,.3,1) 256ms both;
}
@keyframes wipe    { from { transform: scaleX(0); } }
@keyframes slideIn { from { opacity: 0; transform: translateX(-16px); } }

.mask { overflow: hidden; display: inline-block; }
.mask > span {
  display: inline-block;
  animation: up 700ms cubic-bezier(.16,1,.3,1) both;
}
@keyframes up { from { transform: translateY(110%); } }

.progress {
  transform-origin: left;
  animation: fill 4000ms linear both;
}
@keyframes fill { from { transform: scaleX(0); } to { transform: scaleX(1); } }

.count {
  animation: count 800ms cubic-bezier(.22,.61,.36,1) both;
