.arrow path {
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  animation: draw 900ms cubic-bezier(.65,0,.35,1) forwards;
}
@keyframes draw { to { stroke-dashoffset: 0; } }

.circle {
