  stroke-dasharray: 1; stroke-dashoffset: 1;
  animation: draw 448ms ease-out 256ms forwards;
}

.bar {
  transform-origin: bottom;
  animation: grow 800ms cubic-bezier(.22,.61,.36,1) both;
}
@keyframes grow { from { transform: scaleY(0); } }

.pin {
  animation: drop 900ms cubic-bezier(.22,.61,.36,1) both;
}
@keyframes drop {
  0%   { transform: translateY(-150px); opacity: 0; }
  70%  { transform: translateY(0); opacity: 1; }
  85%  { transform: translateY(-14px); }
  100% { transform: translateY(0); }
}

.end-btn {
  animation: pop 520ms cubic-bezier(.34,1.56,.64,1) both;
}
.end-btn + .end-btn { animation-delay: 208ms; }
@keyframes pop { from { transform: scale(.6); opacity: 0; } }

// 0 → 12840 까지 1400ms 동안 easeOut으로 올리기
const t0 = performance.now();
function tick(now) {
  const u = Math.min(1, (now - t0) / 1400);
  el.textContent = Math.round(12840 * (1 - Math.pow(1 - u, 3))).toLocaleString();
  if (u < 1) requestAnimationFrame(tick);
}
requestAnimationFrame(tick);

