.blur-b { animation: blurIn  800ms cubic-bezier(.65,0,.35,1) both; }
@keyframes blurOut { to   { filter: blur(20px); opacity: 0; } }
@keyframes blurIn  { from { filter: blur(20px); opacity: 0; } }

.spin-in {
  animation: spinIn 640ms cubic-bezier(.16,1,.3,1) both;
}
@keyframes spinIn {
  from { transform: rotate(-90deg) scale(.5); opacity: 0; }
  to   { transform: rotate(0) scale(1);       opacity: 1; }
}

.slice {
  transform-origin: top;
  animation: open 560ms cubic-bezier(.65,0,.35,1) both;
}
/* 줄마다 animation-delay를 i × 60ms 로 */
@keyframes open { to { transform: scaleY(0); } }

.leak {
  background: linear-gradient(100deg, transparent 30%, #ffc878 50%, transparent 70%);
  mix-blend-mode: screen;
  animation: leak 1000ms cubic-bezier(.65,0,.35,1) both;
}
@keyframes leak { from { transform: translateX(-100%); } to { transform: translateX(100%); } }

.whip-a { animation: whipOut 360ms cubic-bezier(.16,1,.3,1) both; }
.whip-b { animation: whipIn  360ms cubic-bezier(.16,1,.3,1) both; }
@keyframes whipOut { to { transform: translateX(-60%); filter: blur(14px); } }
@keyframes whipIn  { from { transform: translateX(60%); filter: blur(14px); } }

.ken-burns {
  animation: kb 4000ms linear both;
}
@keyframes kb { to { transform: scale(1.2) translate(-4%, -3%); } }

.shake {
  animation: shake 420ms linear both;
}
@keyframes shake {
  20%  { transform: translate(-8px, 4px) rotate(-.6deg); }
  40%  { transform: translate(6.4px, -3.2px) rotate(.5deg); }
  60%  { transform: translate(-4.8px, 2.4px) rotate(-.3deg); }
  100% { transform: none; }
}

.rgb-r { animation: splitR 360ms linear both; mix-blend-mode: screen; }
.rgb-b { animation: splitB 360ms linear both; mix-blend-mode: screen; }
@keyframes splitR { 50% { transform: translateX(6px); } }
@keyframes splitB { 50% { transform: translateX(-6px); } }

.grain {
  background-image: radial-gradient(...);
  mix-blend-mode: overlay;
  opacity: 0.22;
  animation: grain 180ms steps(3, end) infinite;
}
@keyframes grain { 0% { transform: translate(0,0);} 33% { transform: translate(-6px,4px);} 66% { transform: translate(5px,-3px);} }

.scan {
  background: repeating-linear-gradient(to bottom, rgba(0,0,0,.35) 0 2px, transparent 2px 4px);
  animation: scan 1200ms linear infinite;
}
.track {
  background: linear-gradient(to bottom, transparent, rgba(255,255,255,.35), transparent);
  animation: track 1200ms linear infinite;
}

.vignette {
  background: radial-gradient(ellipse at center, transparent 35%, rgba(0,0,0,.92) 100%);
  animation: vig 1400ms cubic-bezier(.65,0,.35,1) infinite;
}
@keyframes vig { 0%,100% { opacity: .2; } 50% { opacity: .9; } }

.speed-ramp {
  animation: ramp 1500ms cubic-bezier(.7,0,.9,.3) both;
}
@keyframes ramp {
  from { transform: translateX(0); }
  to   { transform: translateX(-60%); }
}

/* 120BPM: 박자 간격 500ms */
.beat {
  animation: punch 500ms cubic-bezier(.22,.61,.36,1) infinite;
}
@keyframes punch {
  0%   { transform: scale(1); }
  12%  { transform: scale(1.06); }
  100% { transform: scale(1); }
}

.grade {
  animation: grade 3000ms cubic-bezier(.65,0,.35,1) both;
}
@keyframes grade {
  from { filter: sepia(.6) saturate(1.3) contrast(1.05); }
  to   { filter: sepia(0)  saturate(.85) contrast(1.15) hue-rotate(-25deg); }
}

.spot {
  background: radial-gradient(circle at 50% 40%, transparent 0%, rgba(0,0,0,.9) 40%);
  animation: spot 900ms cubic-bezier(.22,.61,.36,1) both;
}
@keyframes spot { from { opacity: 0; } to { opacity: 1; } }

.left  { clip-path: inset(0 50% 0 0); animation: inL 640ms cubic-bezier(.16,1,.3,1) both; }
.right { clip-path: inset(0 0 0 50%); animation: inR 640ms cubic-bezier(.16,1,.3,1) both; }
@keyframes inL { from { clip-path: inset(0 100% 0 0); } }
@keyframes inR { from { clip-path: inset(0 0 0 100%); } }

.pip {
  transform-origin: bottom right;
  animation: pipIn 560ms cubic-bezier(.34,1.56,.64,1) both;
}
@keyframes pipIn { from { transform: scale(.4); opacity: 0; } }

.spark {
  animation: spark 700ms cubic-bezier(.22,.61,.36,1) both;
}
@keyframes spark {
  0%   { transform: scale(0) rotate(0);     opacity: 0; }
  50%  { transform: scale(1.2) rotate(90deg); opacity: 1; }
  100% { transform: scale(0) rotate(180deg); opacity: 0; }
}

.mosaic-block {
  transform: scale(0);
  animation: block 500ms cubic-bezier(.22,.61,.36,1) both;
}
@keyframes block { to { transform: scale(1); } }

.glitch { position: relative; }
.glitch::before, .glitch::after {
  content: attr(data-text); position: absolute; inset: 0;
  animation: g 420ms steps(4, end) infinite;
}
.glitch::before { color: #ff3b5c; }
.glitch::after  { color: #3bc7ff; }

.rec {
  color: #ff3b5c;
  animation: blink 1000ms steps(1, end) infinite;
}
@keyframes blink { 0%,50% { opacity: 1; } 51%,100% { opacity: 0; } }

.neon {
  border: 3px solid #ff3bd4;
  border-radius: 10px;
  animation: neon 1100ms cubic-bezier(.65,0,.35,1) infinite;
}
@keyframes neon {
  0%,100% { opacity: .5; box-shadow: 0 0 7.2px #ff3bd4; }
  50%     { opacity: 1;  box-shadow: 0 0 18px #ff3bd4, inset 0 0 18px #ff3bd4; }
}

// 매 프레임 입자 6개 생성, 위로 올라가며 수명에 따라 색 변경
for (const q of particles) {
  q.y -= q.vy;
  q.x += Math.sin(q.life * .25 + q.sw) * .3;
  ctx.fillStyle = colorByLife(q.life / q.max);   // 흰 → 노랑 → 주황 → 재
  ctx.fillRect(q.x, q.y, 1, 1);                 // 1px = 픽셀 4px
}

// 1) 흰 섬광 → 2) 충격파 링 확대 → 3) 파편 방사형 발사 + 중력
ring.radius = t * 1300ms * .5;
ring.alpha  = 1 - t;
for (const q of debris) {
  q.d = q.speed * Math.min(1, t * 1.6);
  q.y += t * t * 0.3 * H;      // 중력
}

// 900ms마다 파문 생성, 나이에 따라 반지름 확대·투명도 감소
if (now - last > 900) rings.push({ x, y, t0: now });
for (const r of rings) {
  const age = (now - r.t0) / 1800;
  ctx.fillRect(r.x + Math.cos(a) * age * W * 0.3, r.y + Math.sin(a) * age * W * 0.3 * .5, 1, 1);
}

// 빗방울 매 프레임 3개, 바닥 닿으면 물방울 3개 튀김
if (drop.y >= floor) {
  for (let k = 0; k < 3; k++) splashes.push({ x: drop.x, y: floor, vx: rnd(-.6, .6), vy: -rnd(.6, 1.4) });
}

// 결정 12개가 중심에서 바깥으로 밀려남, 십자 모양
for (const s of shards) {
  const d = s.dist * Math.min(1, t * 1.4);
  drawPlus(cx + Math.cos(s.a) * d, cy + Math.sin(s.a) * d * .6);
}

// 점 사이를 10마디로 나누고 마디마다 ±8px 흔들림, 매 프레임 새로 그림
const pts = segmentsBetween(a, b, 10, 8);
drawPolyline(pts, '#e8f6ff');

// 타원 픽셀 동전: 가로 반지름 = R × |cos(t × 3)|
const sx = Math.max(.12, Math.abs(Math.cos(t * 3)));
if ((x / sx) ** 2 + y * y <= R * R) drawPixel(x, y, rimOrFace);

// 십자 픽셀을 위로 0.35px/frame씩 이동, 생성 확률 0.25
for (const q of crosses) {
  q.y -= .35;
  drawPlus(q.x, q.y, q.color);
}

// 눈송이 70개, 깊이 z에 따라 낙하 속도·크기 결정
flake.y += .25 + flake.z * .5;
flake.x += Math.sin(t * 1.5 + flake.ph) * 0.4 * .3;

// 반딧불 14마리: 사인 궤적 이동 + 사인 점멸
const x = cx + Math.sin(t * f + ph) * ax;
const on = Math.sin(t * 1.6 * 2 + bp) > -.2;

// 입자 80개: 반지름 감소, 각속도 ∝ r^-1.5 (안쪽이 빠름)
q.r -= 0.6;
q.a += .01 / Math.pow(Math.max(q.r / S, .2), 1.5);
if (q.r < S * .16) respawn(q);

// 1) 세로 축소 (0~70%) → 2) 가로 축소로 점 (70~100%)
const h = H * (1 - t / .7) * .5 + .5;
ctx.fillRect(0, cy - h, W, h * 2);

// 구름 9개: 확대(0~33%) 후 투명(40~100%), 위로 떠오름
const grow = Math.min(1, t * 3);
ctx.globalAlpha = 1 - Math.max(0, (t - .4) / .6);

/* 세로 스크롤 웹툰 컷 연출 */
.panel.left  { animation: inL 2000ms cubic-bezier(.2,1.2,.4,1) both; }
