/* 쇼핑몰: 포물선 투척 + 카운터 */
function addToCart(el) {
  const fly = clone(el);
  // x 직선, y = lerp - 4·H·t(1-t)  (H = 90px)
  fly.animate(parabola(el, cart, 90), { duration: 2000, easing: 'linear' });
  fly.finished.then(() => { counter.set(n => n + 1); cart.bump(); });
}

